#if UNITY_EDITOR || DEVELOPMENT_BUILD
 readonly Stack<IEnumerator> steps=new Stack<IEnumerator>();readonly List<string> records=new List<string>();readonly List<float> frames=new List<float>();CornholeMatch m;Keyboard keyboard;Gamepad pad,replacement;InputSettings original,probe;string folder,flag;bool failed,finished;float maximumBudget;int checks;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Launch(){foreach(var f in new[]{"-tsCornhole","-tsCornholeAI","-tsCornholeViews","-tsCornholeGuards"})if(Array.IndexOf(Environment.GetCommandLineArgs(),f)>=0){var g=new GameObject("Cornhole explicit development validation");DontDestroyOnLoad(g);g.AddComponent<CornholeSmoke>().flag=f;return;}}
 bool hadCameraPreference;int previousCameraPreference;
 void Start(){hadCameraPreference=SportsPrefs.HasKey(SportsCameraOptions.PreferenceKey);previousCameraPreference=SportsPrefs.GetInt(SportsCameraOptions.PreferenceKey);SportsCameraOptions.Set(true);folder=LWS.TruckSports.SportsEvidencePaths.Folder("CornholeSmoke");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"results.txt"),"RUNNING "+flag+" "+DateTime.UtcNow.ToString("O"));if(Application.companyName!="LWS Truck Sports Validation"&&!LWS.TruckSports.SportsProbeInputIsolation.Active){Finish(2);return;}original=InputSystem.settings;probe=Instantiate(original);probe.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;InputSystem.settings=probe;keyboard=InputSystem.AddDevice<Keyboard>("Cornhole software keyboard");Application.logMessageReceived+=Log;steps.Push(Run());}
 void Log(string msg,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){failed=true;records.Add("RUNTIME ERROR "+msg+" "+stack);}}
 void Update(){if(finished)return;if(m!=null&&m.InMatch&&!m.Paused&&!m.Finished){frames.Add(Time.unscaledDeltaTime);foreach(var c in m.courses)if(c.Current!=null)maximumBudget=Mathf.Max(maximumBudget,c.Current.UsedAftertouch);}try{while(steps.Count>0){var s=steps.Peek();if(!s.MoveNext()){steps.Pop();continue;}if(s.Current is IEnumerator nested){steps.Push(nested);continue;}return;}Finish(failed?2:0);}catch(Exception e){records.Add("FAIL "+e);Debug.LogError("CORNHOLE_SMOKE_FAIL "+e);Finish(2);}}
 void OnApplicationQuit(){if(!finished){records.Add("INTERRUPTED before completion marker");File.WriteAllLines(Path.Combine(folder,"results.txt"),records);}}
 void Finish(int code){if(hadCameraPreference)SportsPrefs.SetInt(SportsCameraOptions.PreferenceKey,previousCameraPreference);else SportsPrefs.DeleteKey(SportsCameraOptions.PreferenceKey);SportsPrefs.Save();finished=true;records.Add("CHECKS "+checks);File.WriteAllLines(Path.Combine(folder,"results.txt"),records);Application.logMessageReceived-=Log;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);if(pad!=null&&pad.added)InputSystem.RemoveDevice(pad);if(replacement!=null&&replacement.added)InputSystem.RemoveDevice(replacement);if(original!=null)InputSystem.settings=original;if(probe!=null)Destroy(probe);Time.timeScale=1;Debug.Log("CORNHOLE_SMOKE_FINISHED code="+code);Application.Quit(code);}
 void Check(bool condition,string name){if(!condition)throw new Exception(name);records.Add("PASS "+name);checks++;Debug.Log("CORNHOLE_PASS "+name);}
 IEnumerator Delay(float seconds){float end=Time.realtimeSinceStartup+seconds;while(Time.realtimeSinceStartup<end)yield return null;}
 IEnumerator Wait(Func<bool> condition,float seconds,string name){float end=Time.realtimeSinceStartup+seconds;while(!condition()){if(Time.realtimeSinceStartup>end)throw new Exception("Timeout "+name+" phase="+(m==null?"none":m.courses[0].Phase.ToString())+" p="+(m==null||m.courses[0].Current==null?Vector3.zero:m.courses[0].Current.body.position));yield return null;}}
 IEnumerator Capture(string name){ScreenCapture.CaptureScreenshot(Path.Combine(folder,name+".png"));yield return Delay(.15f);}
 void Keys(params Key[] keys){InputSystem.QueueStateEvent(keyboard,new KeyboardState(keys));}
 void Pose(CornholeTruck t,Vector3 local,Vector3 velocity){var position=t.course.board.TransformPoint(local);t.transform.SetPositionAndRotation(position,t.course.board.rotation);t.body.position=position;t.body.rotation=t.course.board.rotation;t.body.linearVelocity=t.course.board.TransformDirection(velocity);t.body.angularVelocity=Vector3.zero;Physics.SyncTransforms();}
 IEnumerator Begin(int count=1){Keys();m.setup.count=count;m.AllAI();for(int i=0;i<count;i++){m.setup.players[i].name="Cornhole AI "+i;m.setup.players[i].difficulty=(BowlingDifficulty)Mathf.Min(i,2);}Check(m.StartMatch(),"begin "+count+" simultaneous courses");yield return Delay(.1f);}
