  yield return Natural();yield return Replay();yield return LaunchVariations();yield return PhysicalScores();yield return InputLifecycle();yield return Layouts();yield return FullGame();yield return Transitions();
 }
 IEnumerator Natural(){yield return Begin();var c=m.courses[0];var t=c.Current;yield return Wait(()=>t.Launched,10,"NWH drive to actual trampoline");Check(t.LaunchCount==1&&t.body.linearVelocity.y>15,"actual contact once-only upward launch");float launchTime=Time.time;Vector3 launchPosition=t.body.position;float peak=t.body.position.y;records.Add("NATURAL LAUNCH p="+t.body.position+" v="+t.body.linearVelocity);yield return Delay(.6f);yield return Capture("03-natural-flight");yield return Delay(2.4f);yield return Capture("03b-natural-apex");Check(t.LaunchCount==1,"multiple collider / sustained contact cannot relaunch");while(!t.Landed&&c.Phase!=CornholePhase.AttemptResult){peak=Mathf.Max(peak,t.body.position.y);if(Time.time-launchTime>25)throw new Exception("natural flight stalled");yield return null;}records.Add("NATURAL_ARC duration="+(Time.time-launchTime)+" peak="+peak+" range="+(t.body.position.z-launchPosition.z));Check(Time.time-launchTime>5&&peak>35,"readable physical flight longer than five seconds with high arc");records.Add("NATURAL LAND p="+t.body.position+" score="+t.Points+" supported="+t.Supported+" ground="+t.Grounded);yield return Capture("04-natural-landing");yield return Wait(()=>c.Attempts>=2,40,"fresh delivery without confirmation");Check(c.trucks[0].Launched&&c.Current!=t,"earlier truck retained, new input body");}
 IEnumerator Replay(){yield return Begin(2);var c=m.courses[0];yield return Wait(()=>c.Phase==CornholePhase.AttemptResult,35,"natural throw finishes for replay");var replay=c.replay;int round=m.Round;int score=c.Provisional;Check(replay.Available&&replay.FrameCount>80&&replay.Play(),"natural recorded replay starts");var position=c.Current.body.position;int attempts=c.Attempts;float otherZ=m.courses[1].Current.body.position.z,otherElapsed=m.courses[1].PhaseElapsed;var otherPhase=m.courses[1].Phase;for(int a=0;a<4;a++){yield return Delay(.25f);yield return Capture("replay-angle-"+replay.Angle);Check(Mathf.Abs(Vector3.Dot(c.chase.transform.right,Vector3.up))<.01f,"replay horizon "+replay.Angle);replay.NextAngle();}for(int rate=0;rate<5;rate++){replay.Rewind();replay.NextSpeed();float before=replay.Clock,wall=Time.realtimeSinceStartup;yield return Delay(.3f);float actual=replay.Clock-before,expected=(Time.realtimeSinceStartup-wall)*replay.Speed;records.Add("REPLAY_RATE speed="+replay.Speed+" actual="+actual+" expected="+expected+" frame="+Time.unscaledDeltaTime);Check(Mathf.Abs(actual-expected)<Time.unscaledDeltaTime*replay.Speed*2+.035f,"independent replay rate "+replay.Speed);}Check(m.Round==round&&c.Attempts==attempts&&c.Provisional==score,"replay does not alter attempts or scoring");Check(Vector3.Distance(position,c.Current.body.position)<.1f,"replay does not move settled authoritative body");Check(m.courses[1].Attempts>1||m.courses[1].Phase!=otherPhase||m.courses[1].PhaseElapsed>otherElapsed+1||Mathf.Abs(m.courses[1].Current.body.position.z-otherZ)>.1f,"other course continues during replay");m.Pause();float clock=replay.Clock;yield return Delay(.25f);Check(replay.Clock==clock,"replay pause preserved");m.Resume();replay.Stop();yield return Delay(.1f);Check(!replay.Playing&&Vector3.Distance(c.chase.transform.position,c.Current.body.position)<.6f,"return to live cab");}
 IEnumerator ReplayControls(){yield return Begin();var c=m.courses[0];yield return Wait(()=>c.Phase==CornholePhase.AttemptResult,35,"controller replay natural result");pad=InputSystem.AddDevice<Gamepad>("Cornhole software replay owner");m.setup.players[0].source=BowlingSource.WholeController;Check(m.Assign(0,pad),"replay whole-pad owner assigned");InputSystem.QueueStateEvent(pad,new GamepadState());yield return Delay(.25f);InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.West));yield return Delay(.1f);Check(c.replay.Playing,"owned West opens replay");InputSystem.QueueStateEvent(pad,new GamepadState());yield return Delay(.15f);int angle=c.replay.Angle;InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.West));yield return Delay(.1f);Check(c.replay.Angle==(angle+1)%4,"owned West changes angle");InputSystem.QueueStateEvent(pad,new GamepadState());yield return Delay(.1f);float speed=c.replay.Speed;InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.South));yield return Delay(.1f);Check(c.replay.Speed!=speed,"owned South changes replay rate");InputSystem.QueueStateEvent(pad,new GamepadState());yield return Delay(.1f);InputSystem.QueueStateEvent(pad,new GamepadState().WithButton(GamepadButton.North));yield return Delay(.1f);Check(c.replay.Clock<.5f,"owned North rewinds");InputSystem.QueueStateEvent(pad,new GamepadState());yield return Delay(.1f);InputSystem.QueueStateEvent(pad,new GamepadState{rightTrigger=1}.WithButton(GamepadButton.East));yield return Delay(.2f);Check(!c.replay.Playing&&!m.setup.players[0].released&&c.Current.command==Vector2.zero,"East returns to cab without held input leakage");InputSystem.QueueStateEvent(pad,new GamepadState());yield return Delay(.2f);Check(m.setup.players[0].released,"neutral restores replay owner's movement");m.AllAI();InputSystem.RemoveDevice(pad);pad=null;}
 IEnumerator AuthorityGuards(){records.Add("Injected lifecycle failure fixtures, not unassisted scoring attempts.");yield return Launched();var c=m.courses[0];var old=c.Current;old.Exclude();typeof(CornholeTruck).GetMethod("Collect",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(old,null);Check(!old.Holed&&old.Points==0&&!old.gameObject.activeSelf,"excluded failure cannot acquire late hole credit");yield return Launched();c=m.courses[0];old=c.Current;Pose(old,new Vector3(3,.3f,0),Vector3.zero);yield return Wait(()=>old.Points==1,8,"authority fixture stable prior body");yield return Wait(()=>c.Attempts==2&&c.Current.Launched,20,"authority fixture next active flight");var current=c.Current;typeof(CornholeTruck).GetField("<Landed>k__BackingField",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(old,false);typeof(CornholeTruck).GetMethod("Land",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(old,null);Check(old.Landed&&c.Current==current&&c.Phase==CornholePhase.Flight&&!current.Landed,"stale-body landing cannot advance current flight");}
