 IEnumerator PhysicalScores(){records.Add("Seeded PhysX scoring poses below are fixtures, not unassisted shots.");yield return Launched();var c=m.courses[0];var t=c.Current;Pose(t,new Vector3(3,.3f,0),Vector3.zero);records.Add("POSE p="+t.body.position+" tr="+t.transform.position+" v="+t.body.linearVelocity+" board="+c.board.position);if(Physics.Raycast(t.body.position+c.board.up,-c.board.up,out var hit,4))records.Add("RAY "+hit.collider.name+" normal="+hit.normal+" point="+hit.point);for(int sample=0;sample<10;sample++){yield return Delay(.2f);records.Add("REST "+sample+" p="+t.body.position+" v="+t.body.linearVelocity+" w="+t.body.angularVelocity+" supported="+t.Supported+" stable="+t.StableTime+" phase="+c.Phase);}yield return Wait(()=>t.Points==1,8,"actual settled top contact");Check(t.Landed&&t.Points==1&&!t.body.isKinematic,"stable board landing scores one and remains physical");var before=t.body.linearVelocity;t.command=Vector2.one;yield return Delay(.2f);Check(t.UsedAftertouch<=c.aftertouchBudget&&t.body.linearVelocity.magnitude<.5f,"no propulsion / aftertouch after board contact");yield return Capture("05-stable-board-one");Pose(t,new Vector3(3,3,0),Vector3.zero);yield return Delay(.1f);t.body.linearVelocity=t.body.angularVelocity=Vector3.zero;t.body.Sleep();yield return Delay(.1f);Check(!t.Supported&&t.Points==0,"sleeping body cannot retain stale board support after contact exit");yield return Wait(()=>c.Phase==CornholePhase.AttemptResult,3,"settled unsupported landing resolves zero without a failure timeout");Check(c.TimeoutCount==0,"stable zero-point result is normal progression");
  yield return Launched();c=m.courses[0];t=c.Current;Pose(t,new Vector3(0,2,c.holeZ),new Vector3(0,-2,0));yield return Wait(()=>c.board.InverseTransformPoint(t.body.position).y<0,4,"partial entry");Check(!t.Holed&&t.Points!=3,"partial overlap cannot count as holed");yield return Wait(()=>t.Holed,6,"whole body downward physical hole passage");Check(t.Points==3&&t.body.isKinematic&&!t.shape.enabled,"hole collected once and no live collision");int score=c.Provisional;yield return Delay(.5f);Check(c.Provisional==score&&score==3,"repeated hole observation scores once");yield return Capture("06-physical-hole");
  yield return Launched();c=m.courses[0];t=c.Current;Pose(t,new Vector3(10,1,0),Vector3.zero);yield return Wait(()=>t.Grounded,6,"actual miss hits surrounding ground");Check(t.Points==0,"off-board ground scores zero");yield return Wait(()=>!t.gameObject.activeSelf,4,"irretrievable lower-ground miss collected without settle timeout");Check(t.Excluded&&!t.Holed&&t.Points==0,"collected miss stays zero and cannot become a hole");
  yield return Launched();c=m.courses[0];t=c.Current;Pose(t,new Vector3(0,.8f,3.6f),Vector3.zero);yield return Wait(()=>t.Points==1,8,"earlier point before push");yield return Wait(()=>c.Attempts==2&&c.Current.Launched,20,"next truck launched physically");var next=c.Current;records.Add("PUSH_BEFORE earlier="+t.body.position+" dynamic="+!t.body.isKinematic+" score="+t.Points);Pose(next,new Vector3(0,.065f,1.9f),new Vector3(0,0,12));yield return Wait(()=>t.TruckImpacts>0,3,"later truck actual impact");yield return Wait(()=>t.body.position.z>c.board.TransformPoint(new Vector3(0,0,3.6f)).z+.05f,3,"later body physically displaces earlier body");Check(t.TruckImpacts>0,"later delivery has physical truck contact provenance");for(int sample=0;sample<10;sample++){yield return Delay(.2f);records.Add("PUSH_SAMPLE p="+t.body.position+" local="+c.board.InverseTransformPoint(t.body.position)+" v="+t.body.linearVelocity+" supported="+t.Supported+" score="+t.Points+" holed="+t.Holed);}yield return Wait(()=>t.Holed||t.Grounded,10,"pushed truck leaves resting spot");records.Add("PUSH outcome hole="+t.Holed+" score="+t.Points+" p="+t.body.position);Check(t.Points==3,"earlier one-point truck pushed through hole becomes three");yield return Capture("07-truck-push");
  yield return KnockOff();yield return Aftertouch();
