 IEnumerator LaunchVariations(){float slow=0,fast=0,angled=0;foreach(int kind in new[]{0,1,2}){yield return Begin();var c=m.courses[0];var t=c.Current;m.setup.players[0].source=BowlingSource.Keyboard;Keys();float speed=kind==0?8:16;var q=Quaternion.Euler(0,kind==2?12:0,0);var p=new Vector3(c.center,.55f,1.1f);t.transform.SetPositionAndRotation(p,q);t.body.position=p;t.body.rotation=q;t.body.linearVelocity=q*Vector3.forward*speed;t.body.angularVelocity=Vector3.zero;Physics.SyncTransforms();yield return Wait(()=>t.Launched,2,"seeded velocity reaches actual trampoline "+kind);Check(t.LaunchCount==1,"contact launch variation exactly once "+kind);records.Add("ENTRY_VARIATION kind="+kind+" p="+t.body.position+" v="+t.body.linearVelocity);if(kind==0)slow=t.body.linearVelocity.z;if(kind==1)fast=t.body.linearVelocity.z;if(kind==2)angled=t.body.linearVelocity.x;yield return Delay(.2f);}Check(fast>slow+1&&angled>1,"entry speed affects range; angle affects lateral flight");}
