 IEnumerator InputLifecycle(){yield return Begin(2);m.setup.players[0].source=m.setup.players[1].source=BowlingSource.Keyboard;Keys(Key.W,Key.UpArrow,Key.LeftArrow);yield return Delay(.15f);Check(m.Drive(0)==new Vector2(0,1)&&m.Drive(1)==new Vector2(-1,1),"two independent keyboard clusters");Keys();yield return Delay(.1f);pad=InputSystem.AddDevice<Gamepad>("Cornhole injected shared pad");m.setup.players[0].source=BowlingSource.LeftStick;m.setup.players[1].source=BowlingSource.RightStick;Check(m.Assign(0,pad)&&m.Assign(1,pad),"left/right sticks share one pad");m.setup.players[1].source=BowlingSource.LeftStick;Check(!m.setup.Validate(out _),"duplicate stick rejected");m.setup.players[1].source=BowlingSource.WholeController;Check(!m.setup.Validate(out _),"whole versus shared conflict rejected");m.setup.players[1].source=BowlingSource.RightStick;m.Gate();InputSystem.QueueStateEvent(pad,new GamepadState());yield return Delay(.2f);InputSystem.QueueStateEvent(pad,new GamepadState{leftStick=new Vector2(.6f,1),rightStick=new Vector2(-.4f,.5f)});yield return Delay(.15f);Check(m.Drive(0).x>.4f&&m.Drive(1).x<-.2f,"independent shared stick routing");float sensitivity=m.settings.sensitivity;m.settings.sensitivity=1;float left=m.Drive(0).x,right=m.Drive(1).x;m.settings.sensitivity=.5f;Check(Mathf.Abs(m.Drive(0).x-left*.5f)<.02f&&Mathf.Abs(m.Drive(1).x-right*.5f)<.02f,"shared steering sensitivity applies independently after stick processing");m.settings.sensitivity=2;Check(Mathf.Abs(m.Drive(0).x-Mathf.Clamp(left*2,-1,1))<.02f&&Mathf.Abs(m.Drive(1).x-Mathf.Clamp(right*2,-1,1))<.02f,"steering sensitivity remains bounded");m.settings.sensitivity=sensitivity;InputSystem.QueueStateEvent(pad,new GamepadState());yield return Delay(.1f);m.AllAI();yield return Begin();var t=m.courses[0].Current;yield return Wait(()=>t.Launched,10,"pause test airborne");var p=t.body.position;var v=t.body.linearVelocity;int attempts=m.courses[0].Attempts,points=m.courses[0].Provisional;m.Pause();yield return 