 IEnumerator Layouts(){foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080)}){Screen.SetResolution(size.x,size.y,false);yield return Delay(.4f);for(int n=1;n<=4;n++){yield return Begin(n);for(int i=0;i<n;i++)m.setup.players[i].name="Alexandra Montgomery "+(i+1);yield return Delay(1.3f);Check(Screen.width==size.x&&Screen.height==size.y,"actual window resolution "+size);for(int i=0;i<n;i++){var c=m.courses[i];Check(c.chase.view.enabled&&c.chase.view.rect==CornholeMatch.ViewRect(n,i),"viewport "+size+" / "+n+" / "+i);m.menus.headers[i].ForceMeshUpdate();records.Add("HEADER "+n+" / "+i+" text="+m.menus.headers[i].text.Replace("\n"," / "));Check(!m.menus.headers[i].isTextTruncated,"long name readable "+n+" / "+i);Check(c.chase.interior.Length>=8&&Vector3.Distance(c.chase.transform.position,c.Current.body.position)<.6f,"default driver-seat view "+n+" / "+i);Check(Vector3.Distance(c.Current.paint.bounds.center,c.Current.body.position)<1.5f,"visible cab aligned with physical truck "+i);}yield return Capture("layout-"+size.x+"-"+n);m.Pause();yield return Capture("pause-"+size.x+"-"+n);m.menus.Show(CornholeScreen.Help);var help=m.menus.pages[4].transform.Find("Rules").GetComponent<TMPro.TMP_Text>();help.ForceMeshUpdate();Check(!help.isTextTruncated,"help page one complete "+size);yield return Capture("help-"+size.x+"-"+n);m.menus.NextHelp();help.ForceMeshUpdate();Check(!help.isTextTruncated,"help page two complete "+size);yield return Capture("help-score-"+size.x+"-"+n);m.menus.Show(CornholeScreen.Pause);m.Resume();}}}
 IEnumerator FullGame(){yield return Begin(4);if(flag=="-tsCornhole")Time.timeScale=3;float start=Time.realtimeSinceStartup,nextProgress=0;long memory=GC.GetTotalMemory(false);int gen0=GC.CollectionCount(0);frames.Clear();var deliveries=new HashSet<string>();var scoredHoles=new HashSet<string>();int[] timeouts=new int[4];bool independent=false;while(!m.Finished){if(Time.realtimeSinceStartup-start>950)throw new Exception("full AI match stalled");for(int i=0;i<4;i++){var c=m.courses[i];if(c.Current!=null){for(int d=0;d<c.Attempts;d++){var b=c.trucks[d];if(b.Launched)deliveries.Add(m.Round+"/"+i+"/"+d);if(b.Holed)scoredHoles.Add(m.Round+"/"+i+"/"+d);if(b.LaunchCount>1)throw new Exception("Duplicate trampoline launch");}CheckBudget(c.Current);}for(int j=0;j<4;j++)if(j!=i)independent|=c.Done&&!m.courses[j].Done;timeouts[i]=c.TimeoutCount;}if(Time.realtimeSinceStartup>nextProgress){nextProgress=Time.realtimeSinceStartup+10;records.Add("PROGRESS round="+m.Round+" totals="+string.Join(",",m.totals)+" attempts="+string.Join(",",Array.ConvertAll(m.courses,c=>c.Attempts+":"+c.Phase+":"+(c.Current==null?Vector3.zero:c.Current.body.position))));File.WriteAllLines(Path.Combine(folder,"progress.txt"),records);}yield return null;}
  Check(m.RoundFinalizations==5,"exactly five round finalizations");Check(independent,"one finished course waits without freezing others");records.Add("PHYSICAL_MATCH launches="+deliveries.Count+" holed="+scoredHoles.Count);for(int i=0;i<4;i++){Check(m.courses[i].Attempts==4&&m.courses[i].RoundLocks==5,"four attempts per round no fifth / five banks "+i);Check(m.totals[i]>=0&&m.totals[i]<=60,"valid cumulative total "+i);records.Add("AI difficulty="+m.setup.players[i].difficulty+" total="+m.totals[i]+" timeouts="+timeouts[i]);}Check(m.winners.Length>0,"final winner or tie");Check(maximumBudget<=2.401f,"shared aftertouch bound throughout match");yield return Capture("complete-four-ai");m.menus.Action("review");yield return Delay(.3f);for(int i=0;i<4;i++)Check(m.courses[i].replay.Playing,"final throw review "+i);yield return Capture("final-replays-four");m.courses[0].replay.Stop();yield return Delay(.15f);Check(m.menus.replayButtons[4].activeSelf,"standings exit remains available after replay stops");m.ReplayStop(0);Check(m.menus.Screen==CornholeScreen.Result,"final review returns to standings");frames.Sort();double sum=0;foreach(float f in frames)sum+=f;records.Add("PERF duration="+(Time.realtimeSinceStartup-start)+" frames="+frames.Count+" meanMs="+(sum/Math.Max(1,frames.Count)*1000)+" p95="+frames[(int)(frames.Count*.95f)]*1000+" p99="+frames[(int)(frames.Count*.99f)]*1000+" maxMs="+frames[frames.Count-1]*1000+" managedDelta="+(GC.GetTotalMemory(false)-memory)+" gen0="+(GC.CollectionCount(0)-gen0)+" GPU="+SystemInfo.graphicsDeviceName+" size="+Screen.width+"x"+Screen.height+" timescale="+Time.timeScale);string name=m.setup.players[0].name;Check(m.StartMatch()&&m.totals[0]==0&&m.Round==1&&m.setup.players[0].name==name,"rematch preserves configuration resets score/body pool");yield return Delay(.2f);}
 void CheckBudget(CornholeTruck t){if(t.UsedAftertouch>t.course.aftertouchBudget+.001f)throw new Exception("aftertouch budget exceeded");}
 IEnumerator Transitions(){for(int i=0;i<3;i++){SportsNavigation.FrontEnd();yield return Delay(.5f);Check(FindAnyObjectByType<CornholeMatch>()==null&&FindObjectsByType<AudioListener>(FindObjectsInactive.Include).Length==1,"scene exit cleanup "+i);SportsNavigation.LoadSport(SportsNavigation.Cornhole);yield return Delay(.5f);m=FindAnyObjectByType<CornholeMatch>();Check(m!=null&&!m.InMatch,"repeat menu entry "+i);}foreach(var sport in new[]{SportsNavigation.Billiards,SportsNavigation.Hockey,SportsNavigation.Bowling,SportsNavigation.AirHockey,SportsNavigation.Wallball}){SportsNavigation.LoadSport(sport);yield return Delay(.6f);Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name==sport,"existing saved sport loads "+sport);}SportsNavigation.FrontEnd();yield return Delay(.3f);Check(!failed,"no runtime errors");}
#endif
}
